import json,csv,gzip,sys
from pathlib import Path
root=Path.cwd();p=root/'data/curation/etymology-lab/das-yerava-20260922';sys.path.insert(0,str(root/'data'))
from etymology_assignments import read_assignments
z=json.load(open(p/'proposed-decisions.json'));seen={a['record']['ID'] for a in z['accepted']+z['held']}|{r['Form_ID'] for r in read_assignments()}
rules=[(['Pire'],['House','Hut'],'d4294','DEDR4294 gives Tamil pirai shed, purai house, Malayalam pura house/hut and Kodagu pore thatched roof. Paniya Pire is compared with the pir-/pur-/por- shelter family, preserving its two source-defined house and hut records.'),(['Palli'],['Hut'],'d4018','DEDR4018 explicitly gives Malayalam paḷḷi hut and Kodagu paḷḷi hut, beside Kannada paḷḷi/haḷḷi settlement. Ravula Palli has the same geminate spelling and hut sense. The Sanskrit pallī comparison does not by itself establish a direct donor.'),(['Kallu'],['Arrack','Toddy'],'d1374','DEDR1374 gives Malayalam/Kannada kaḷḷu toddy and Kodagu kaḷḷï alcoholic liquor; central branches include country spirit and fermented liquor. Das Kallu is separately elicited for Paniya Arrack and Ravula Toddy. The source distinction is preserved, without assuming a particular production method or donor from the Indo-Aryan comparisons.'),(['Pagelu'],['Day time'],'d3805','DEDR3805 explicitly gives Tulu pagelů daytime, Kannada pagal daytime and Malayalam pakal morning/daytime. Das Pagelu in both lects preserves the full daytime noun. The questioned lustre comparanda elsewhere in the article are not used.'),(['Iravu'],['Night'],'d2552','DEDR2552 explicitly gives Tamil and Malayalam iravu night, alongside the related southern darkness/night formations. Das Paniya Iravu matches the full night noun rather than a similarly spelled death or filling verb.'),(['Savu','Chavu'],['Death'],'d2426','DEDR2426 explicitly gives Kannada sāvu and Malayalam/Tamil cāvu death, with Kodagu cāvu corpse. Das Savu/Chavu preserve the corresponding death nouns; they are compared as existing nominal members of the full article, not analysed as newly derived from an unattested local verb. The Sanskrit śava comparison remains qualified.'),(['Ba'],['Come'],'d5270','DEDR5270 explicitly gives Kannada bā and Kodagu bā within bar- come, alongside Tamil vā and Malayalam vā. Das Ba is a compatible short verbal form; the source only prints Come, so no imperative grammatical tag is added.'),(['Po'],['Go'],'d4572','DEDR4572 gives Kodagu pō- and Malayalam pōka go, Kannada pō/pōgu and Tulu pōpini go. Das Po agrees with the p-initial go stem. The cached Tamil opening is truncated, so the proposal relies on the complete neighbouring-language descriptions rather than supplying missing Tamil text.'),(['Bulaku','Boli'],['Light'],'d5496','DEDR5496(a) explicitly gives Tulu buḷaků brightness, Kannada beḷaku light and Kodagu boḷakï lamp/boḷi light. Das Ravula Bulaku and Paniya Boli preserve the distinct light formations. The whole article is the node scope; the displayed butter compound does not replace these meanings.')]
n=0
for r in json.load(open(p/'survey-inventory.json')):
 if r['ID'] in seen:continue
 for forms,glosses,d,ev in rules:
  if r['Form'] in forms and r['Gloss'] in glosses:
   z['accepted'].append(dict(record=r,parent=d,kind='reflex',citation=f'dedr[entry {d[1:]}];'+r['Source'],evidence=ev+' Popular spelling remains unchanged. Comparative family membership is proposed; the documented multilingual contact leaves inheritance versus local transmission subject to review.',status='pending-review'));n+=1;seen.add(r['ID']);break
(p/'proposed-decisions.json').write_text(json.dumps(z,ensure_ascii=False,indent=2)+'\n')
used={a['parent'] for a in z['accepted']};a={r['Entry_ID']:r for r in csv.DictReader(gzip.open(root/'data/data/dedr/entry-texts-audit.csv.gz','rt')) if r['Entry_ID'] in used and r['Status']!='duplicate-excluded'};(p/'primary-evidence.json').write_text(json.dumps(a,ensure_ascii=False,indent=2)+'\n');print('added',n)
